import{c as a,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E9%9D%9E%E8%BF%9E%E7%BB%AD%E5%86%99%E6%A8%A1%E5%BC%8F%E7%A4%BA%E6%84%8F%E5%9B%BE.BqaZCkqS.png",i="/assets/%E8%BF%9E%E7%BB%AD%E5%86%99%E6%A8%A1%E5%BC%8F%E7%A4%BA%E6%84%8F%E5%9B%BE.B9Sn-erX.png",m=JSON.parse('{"title":"GetTensorC","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetTensorC","slug":"gettensorc"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetTensorC.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetTensorC.md"}'),p={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetTensorC.md"};function o(r,t,d,c,h,u){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="gettensorc" tabindex="-1">GetTensorC <a class="header-anchor" href="#gettensorc" aria-label="Permalink to &quot;GetTensorC&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Iterate后，获取一块或者两块C矩阵片，可以直接输出到GM tensor中，也可以输出到VECIN tensor中。当<a href="./MatmulConfig.html#table1761013213153">MatmulConfig</a>参数中的ScheduleType取值为ScheduleType::INNER_PRODUCT时，获取一块C矩阵片；当<a href="./MatmulConfig.html#table1761013213153">MatmulConfig</a>参数中的ScheduleType取值为ScheduleType::OUTER_PRODUCT时，获取两块C矩阵片。</p><p>该接口和<a href="./Iterate.html">Iterate</a>接口配合使用，用于在调用Iterate完成迭代计算后，根据<a href="./MatmulConfig.html#table1761013213153">MatmulConfig</a>参数中的ScheduleType取值获取一块或两块baseM * baseN大小的矩阵分片。</p><p>迭代获取C矩阵分片的过程分为同步和异步两种模式：</p><ul><li>**同步：**执行完一次Iterate后执行一次GetTensorC，需要同步等待C矩阵分片获取完成。</li><li>**异步：**调用Iterate后，无需立即调用GetTensorC同步等待，可以先执行其他逻辑，待需要获取结果时再调用GetTensorC。异步方式可以减少同步等待，提高并行度，开发者对计算性能要求较高时，可以选用该方式。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>获取C矩阵，输出至VECIN</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetTensorC(const LocalTensor&lt;DstT&gt;&amp; co2Local, uint8_t enAtomic = 0, bool enSequentialWrite = false)</span></span></code></pre></div><ul><li>支持同步模式</li><li>支持异步模式</li></ul></li><li><p>获取C矩阵，输出至GM</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetTensorC(const GlobalTensor&lt;DstT&gt;&amp; gm, uint8_t enAtomic = 0, bool enSequentialWrite = false)</span></span></code></pre></div><ul><li>支持同步模式</li><li>支持异步模式</li></ul></li><li><p>获取C矩阵，同时输出至GM和VECIN</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetTensorC(const GlobalTensor&lt;DstT&gt; &amp;gm, const LocalTensor&lt;DstT&gt; &amp;co2Local, uint8_t enAtomic = 0, bool enSequentialWrite = false)</span></span></code></pre></div><ul><li>支持同步模式</li><li>支持异步模式</li><li>纯Cube模式（只有矩阵计算）模式暂不支持该接口</li><li>Atlas 200I/500 A2 推理产品暂不支持同时输出至GM和VECIN</li></ul></li><li><p>获取异步场景用于缓存结果的Workspace上的C矩阵，后续使用过程由开发者自行控制</p><p>C矩阵输出到VECIN时，分配给VECIN的Unified Buffer的大小会影响Matmul计算的力度，分配给VECIN的大小过小时，无法充分利用硬件算力。提供该接口支持返回缓存在Workspace上的C矩阵，由开发者自行控制后续使用过程。</p><p>注意，在初始化时，C矩阵的逻辑位置应设置为TPosition::VECIN，调用该接口获取缓存的C矩阵后，自行拷贝到Unified Buffer。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline GlobalTensor&lt;DstT&gt; GetTensorC(uint8_t enAtomic = 0, bool enSequentialWrite = false)</span></span></code></pre></div><ul><li>支持异步模式</li></ul></li></ul><p>以下接口中的doPad、height、width、srcGap、dstGap参数待废弃，使用过程中无需传入，保持默认值即可；上文介绍的输出至VECIN的原型实际为不传入默认值的函数原型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true, bool doPad = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetTensorC(const LocalTensor&lt;DstT&gt;&amp; c, uint8_t enAtomic = 0, bool enSequentialWrite = false, uint32_t height = 0, uint32_t width = 0, uint32_t srcGap = 0, uint32_t dstGap = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>设置同步或者异步模式：同步模式设置为true；异步模式设置为false。 Ascend 950PR/Ascend 950DT支持异步模式。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持异步模式。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持异步模式。 Atlas 推理系列产品AI Core不支持异步模式。 Atlas 200I/500 A2 推理产品不支持异步模式。 Kirin X90支持异步模式。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>c/co2Local</td><td>输出</td><td>取出C矩阵到VECIN。 Ascend 950PR/Ascend 950DT支持的数据类型为half、float、bfloat16_t、int32_t、int8_t、fp8_e4m3fn_t、hifloat8_t。数据格式支持ND、NZ。 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品支持的数据类型为half、float、bfloat16_t、int32_t、int8_t。数据格式支持ND、NZ。 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品支持的数据类型为half、float、bfloat16_t、int32_t、int8_t。数据格式支持ND、NZ。 针对Atlas 推理系列产品AI Core支持的数据类型为half、float、int8_t、int32_t。数据格式支持NZ。 Atlas 200I/500 A2 推理产品支持的数据类型为half、float、bfloat16_t、int32_t。数据格式支持ND、NZ。 Kirin X90支持的数据类型为half、int8_t、int32_t。 Kirin 9030支持的数据类型为half。</td></tr><tr><td>gm</td><td>输出</td><td>取出C矩阵到GM，数据格式可以为ND或NZ。 Ascend 950PR/Ascend 950DT支持的数据类型为half、float、bfloat16_t、int32_t、int8_t、fp8_e4m3fn_t、hifloat8_t 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品支持的数据类型为half、float、bfloat16_t、int32_t、int8_t 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品支持的数据类型为half、float、bfloat16_t、int32_t、int8_t 针对Atlas 推理系列产品AI Core支持的数据类型为half、float、int8_t、int32_t Atlas 200I/500 A2 推理产品支持的数据类型为half、float、bfloat16_t、int32_t Kirin X90支持的数据类型为half、int8_t、int32_t Kirin 9030支持的数据类型为half</td></tr><tr><td>enAtomic</td><td>输入</td><td>是否开启Atomic操作，默认值为0。 参数取值： 0：不开启Atomic操作 1：开启AtomicAdd累加操作 2：开启AtomicMax求最大值操作 3：开启AtomicMin求最小值操作 对于Atlas 推理系列产品AI Core，只有输出位置是GM才支持开启Atomic操作。 对于Atlas 200I/500 A2 推理产品，只有输出位置是GM才支持开启Atomic操作。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>是否开启连续写模式（连续写，写入[baseM, baseN]；非连续写，写入[singleCoreM, singleCoreN]中对应的位置），默认值false（非连续写模式）。 注意：非连续写模式，内部会按照迭代顺序算好偏移，开发者不需要关注；如果开发者需要决定排布顺序，可以选择连续写模式，自行按照设定的偏移进行搬运操作。 对于Atlas 200I/500 A2 推理产品，只支持非连续写模式。</td></tr></tbody></table><p><strong>图 1</strong> 非连续写模式示意图<br><img src="`+l+'" alt="" title="非连续写模式示意图"></p><p><strong>图 2</strong> 连续写模式示意图<br><img src="'+i+`" alt="" title="连续写模式示意图"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>传入的C矩阵地址空间大小需要保证不小于baseM * baseN。</li><li>异步场景时，需要使用一块临时空间来缓存Iterate计算结果，调用GetTensorC时会在该临时空间中获取C的矩阵分片。临时空间通过<a href="./SetWorkspace.html">SetWorkspace</a>接口进行设置。SetWorkspace接口需要在Iterate接口之前调用。</li><li>当使能MixDualMaster（双主模式）场景时，即模板参数<a href="./MatmulConfig.html#p9218181073719">enableMixDualMaster</a>设置为true，不支持使用该接口。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>获取C矩阵，输出至VECIN</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 同步模式样例</span></span>
<span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(ubCmatrix); </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 异步模式样例</span></span>
<span class="line"><span>mm.template Iterate&lt;false&gt;();</span></span>
<span class="line"><span>// 其他操作</span></span>
<span class="line"><span>for (int i = 0; i &lt; singleM / baseM * singleN / baseN; ++i) {   </span></span>
<span class="line"><span>    mm.template GetTensorC&lt;false&gt;(ubCmatrix); </span></span>
<span class="line"><span>    // 其他操作</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>获取C矩阵，输出至GM，同步模式样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(gm); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>获取C矩阵，同时输出至GM和VECIN，同步模式样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(gm, ubCmatrix); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>获取API接口返回的GM上的C矩阵，手动拷贝至UB，异步模式样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// BaseM * BaseN = 128 *256</span></span>
<span class="line"><span>mm.SetTensorA(gmA);</span></span>
<span class="line"><span>mm.SetTensorB(gmB);</span></span>
<span class="line"><span>mm.SetTail(singleM, singleN, singleK);</span></span>
<span class="line"><span>mm.template Iterate&lt;false&gt;(); </span></span>
<span class="line"><span>// 其他操作</span></span>
<span class="line"><span>for (int i = 0; i &lt; singleM / baseM * singleN / baseN; ++i) {  </span></span>
<span class="line"><span>    // 获取每次计算的BaseM*BaseN的数据128*256 </span></span>
<span class="line"><span>    GlobalTensor&lt;T&gt; global = mm.template GetTensorC&lt;false&gt;();</span></span>
<span class="line"><span>    for(int j = 0; j &lt; 4; ++j) {</span></span>
<span class="line"><span>        LocalTensor local = que.AllocTensor&lt;half&gt;(); // 分配64*128大小的UB空间</span></span>
<span class="line"><span>        DataCopy(local, global[64 * 128 * i], 64 * 128); // 将GM的数据拷贝进UB中，进行后续的Vector操作</span></span>
<span class="line"><span>        // 其他Vector 操作</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,25)])])}const b=a(p,[["render",o]]);export{m as __pageData,b as default};
